1	/**
2	 * 内部运营看板（评测用例的输入文件，故意留着几处性能问题给人优化）。
3	 *
4	 * 这份文件是 ask 用例 `ask-<id>` 的工作区输入（`context.repo_fixture`），
5	 * 不是仓库自己的产品代码——改它之前先看 `candidates/skills/react-best-practices/evals/cases/` 下的用例。
6	 */
7	import { useEffect, useState } from 'react';
8	
9	export interface Order {
10	  id: string;
11	  user: string;
12	  amount: number;
13	  status: 'paid' | 'pending' | 'refunded';
14	  region: string;
15	}
16	
17	export interface Metric {
18	  key: string;
19	  label: string;
20	  value: number;
21	}
22	
23	export interface User {
24	  id: string;
25	  name: string;
26	  team: string;
27	}
28	
29	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
30	
31	/** 模拟接口：各自要几百毫秒 */
32	export async function fetchOrders(): Promise<Order[]> {
33	  await sleep(600);
34	  return Array.from({ length: 480 }, (_, i) => ({
35	    id: `ord-${i}`,
36	    user: `u-${i % 60}`,
37	    amount: Math.round((i * 37) % 900) + 20,
38	    status: (['paid', 'pending', 'refunded'] as const)[i % 3],
39	    region: ['华东', '华北', '华南', '西南'][i % 4],
40	  }));
41	}
42	
43	export async function fetchMetrics(): Promise<Metric[]> {
44	  await sleep(650);
45	  return [
46	    { key: 'gmv', label: '今日 GMV', value: 128430 },
47	    { key: 'orders', label: '订单数', value: 1742 },
48	    { key: 'refund', label: '退款率', value: 0.031 },
49	  ];
50	}
51	
52	export async function fetchUsers(): Promise<User[]> {
53	  await sleep(550);
54	  return Array.from({ length: 60 }, (_, i) => ({ id: `u-${i}`, name: `成员 ${i + 1}`, team: ['增长', '交易', '履约'][i % 3] }));
55	}
56	
57	export function Dashboard() {
58	  const [orders, setOrders] = useState<Order[]>([]);
59	  const [metrics, setMetrics] = useState<Metric[]>([]);
60	  const [users, setUsers] = useState<User[]>([]);
61	  const [rows, setRows] = useState<Order[]>([]);
62	  const [query, setQuery] = useState('');
63	  const [status, setStatus] = useState<'all' | Order['status']>('all');
64	  const [width, setWidth] = useState(window.innerWidth);
65	
66	  // 三份数据一个接一个地取
67	  useEffect(() => {
68	    const load = async () => {
69	      const o = await fetchOrders();
70	      setOrders(o);
71	      const m = await fetchMetrics();
72	      setMetrics(m);
73	      const u = await fetchUsers();
74	      setUsers(u);
75	    };
76	    void load();
77	  }, []);
78	
79	  // 筛选 + 排序放进 effect，并且每敲一个字就重算一遍
80	  useEffect(() => {
81	    const next = orders
82	      .filter((o) => (status === 'all' ? true : o.status === status))
83	      .filter((o) => (query ? o.user.toLowerCase().includes(query.toLowerCase()) : true))
84	      .sort((a, b) => b.amount - a.amount);
85	    setRows(next);
86	  }, [orders, query, status]);
87	
88	  // 每次渲染都挂一个监听
89	  window.addEventListener('resize', () => setWidth(window.innerWidth));
90	
91	  const userOf = (id: string) => users.find((u) => u.id === id);
92	
93	  return (
94	    <div className="dashboard" style={{ width: width - 32 }}>
95	      <header>
96	        <h1>运营看板</h1>
97	        <input
98	          placeholder="按成员筛选"
99	          value={query}
100	          onChange={(e) => setQuery(e.target.value)}
101	        />
102	        <select value={status} onChange={(e) => setStatus(e.target.value as Order['status'])}>
103	          <option value="all">全部</option>
104	          <option value="paid">已支付</option>
105	          <option value="pending">待支付</option>
106	          <option value="refunded">已退款</option>
107	        </select>
108	      </header>
109	
110	      <section className="metrics">
111	        {metrics.map((m) => (
112	          <div className="metric" key={m.key} style={{ padding: 12 }}>
113	            <span>{m.label}</span>
114	            <strong>{m.value}</strong>
115	          </div>
116	        ))}
117	      </section>
118	
119	      <p>
120	        共 {rows.length} 条 / 成员 {users.length} 人
121	      </p>
122	
123	      <table>
124	        <thead>
125	          <tr>
126	            <th>订单</th>
127	            <th>成员</th>
128	            <th>金额</th>
129	            <th>状态</th>
130	            <th>区域</th>
131	          </tr>
132	        </thead>
133	        <tbody>
134	          {rows.map((o, i) => (
135	            <Row
136	              key={i}
137	              order={o}
138	              name={userOf(o.user)?.name ?? o.user}
139	              style={{ padding: 8 }}
140	              onPick={() => setQuery(o.user)}
141	            />
142	          ))}
143	        </tbody>
144	      </table>
145	    </div>
146	  );
147	}
148	
149	interface RowProps {
150	  order: Order;
151	  name: string;
152	  style: React.CSSProperties;
153	  onPick: () => void;
154	}
155	
156	function Row({ order, name, style, onPick }: RowProps) {
157	  return (
158	    <tr style={style} onClick={onPick}>
159	      <td>{order.id}</td>
160	      <td>{name}</td>
161	      <td>{order.amount}</td>
162	      <td>{order.status}</td>
163	      <td>{order.region}</td>
164	    </tr>
165	  );
166	}
